Demonstrate with the class:

int main() {
    // Demo with int
    int intArr[] = {1, 5, 10, 3, 7};
    alignArray(intArr, 5, 5);
    for (int x : intArr) cout &lt;&lt; x &lt;&lt; " ";  // 3 5 8 5 5
    cout &lt;&lt; endl;

