        this.isAlive = true;
        System.out.println("The Human " + name + " was born");
    }

    @Override
    void die() {
        this.isAlive = false;
        System.out.println("The Human " + name + " has died");
    }
}

// Dog.java
class Dog extends Creature {
    @Override
    void bear() {
