List&lt;Integer&gt; processed = numbers.stream()
    .filter(n -&gt; n &gt; 5)
    .distinct()
    .sorted()
    .collect(Collectors.toList());

System.out.println("Original: " + numbers);      // [5, 9, 8, 8, 1]
System.out.println("Processed: " + processed);   // [8, 9]
More Stream Examples:
// Count elements
