    .filter(n -&gt; n &gt; 5)
    .count();
System.out.println("Count: " + count);  // 3

// Find first
Optional&lt;Integer&gt; first = numbers.stream()
    .filter(n -&gt; n &gt; 5)
    .findFirst();
System.out.println("First: " + first.get());  // 9

// Map transformation
