        List&lt;String&gt; names = Arrays.asList("Charlie", "David", "Eve");
        List&lt;Person&gt; people = names.stream()
            .map(Person::new)  // Creates Person for each name
            .collect(Collectors.toList());
        people.forEach(System.out::println);
        // Charlie (0)
        // David (0)
        // Eve (0)
    }
}
