3.2. Фигуры: площадь и периметр (Лаба 2, Пример 1)
Реализуйте классы Circle, Rectangle, Triangle, Square, Ellipse с расчётом площади и периметра. Используйте наследование, чтобы сократить дублирование.


Нажмите, чтобы увидеть решение

import static java.lang.Math.PI; // Import PI for calculations
import static java.lang.Math.sqrt; // Import sqrt for calculations

// Shape.java
// The abstract Shape class defines common methods for all shapes.
abstract class Shape {
    // All shapes will have a name, though not explicitly asked, it's good practice.
    private String name;

    public Shape(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }

    // Abstract methods for calculating area and perimeter,
    // to be implemented by concrete shape subclasses.
    public abstract double getArea();
    public abstract double getPerimeter();

    @Override
    public String toString() {
        return "Shape: " + name;
    }
}

// Circle.java
// Circle extends Shape and implements area and perimeter calculation for a circle.
class Circle extends Shape {
    private double radius;

    public Circle(double radius) {
        super("Circle"); // Set the name of the shape
        if (radius &lt;= 0) {
            throw new IllegalArgumentException("Radius must be positive.");
        }
        this.radius = radius;
    }

    public double getRadius() {
        return radius;
    }

    // Area of a circle: PI * r^2
    @Override
    public double getArea() {
        return PI * radius * radius;
    }

    // Perimeter (circumference) of a circle: 2 * PI * r
    @Override
    public double getPerimeter() {
        return 2 * PI * radius;
    }

    @Override
    public String toString() {
        return super.toString() + ", Radius: " + radius;
    }
}

// Rectangle.java
// Rectangle extends Shape and implements area and perimeter calculation for a rectangle.
class Rectangle extends Shape {
    private double length;
    private double width;

    public Rectangle(double length, double width) {
        super("Rectangle"); // Set the name of the shape
        if (length &lt;= 0 || width &lt;= 0) {
            throw new IllegalArgumentException("Length and width must be positive.");
        }
        this.length = length;
        this.width = width;
    }

    public double getLength() {
        return length;
    }

    public double getWidth() {
        return width;
    }

    // Area of a rectangle: length * width
    @Override
    public double getArea() {
        return length * width;
    }

    // Perimeter of a rectangle: 2 * (length + width)
    @Override
    public double getPerimeter() {
        return 2 * (length + width);
    }

    @Override
    public String toString() {
        return super.toString() + ", Length: " + length + ", Width: " + width;
    }
}

// Square.java
// Square extends Rectangle, demonstrating inheritance for specialized shapes.
class Square extends Rectangle {
    public Square(double side) {
        // Call the Rectangle constructor with length and width being the same (side)
        super(side, side);
        super.name = "Square"; // Override the name from "Rectangle" to "Square"
    }

    // No need to override getArea() or getPerimeter() as Rectangle's methods work correctly.
    // However, we can add a specific toString for Square.
    @Override
    public String toString() {
        // Using getLength() from the parent Rectangle class which is the side.
        return super.toString().replace("Length: " + getLength() + ", Width: " + getLength(), "Side: " + getLength());
    }
}

// Triangle.java
// Triangle extends Shape and implements area and perimeter calculation for a triangle.
// For simplicity, area uses base and height, and perimeter uses three sides.
class Triangle extends Shape {
    private double sideA;
    private double sideB;
    private double sideC;
    private double base; // For area calculation
    private double height; // For area calculation

    // Constructor for perimeter (given three sides)
    public Triangle(double sideA, double sideB, double sideC) {
        super("Triangle");
        // Basic check for valid triangle (triangle inequality theorem)
        if (sideA &lt;= 0 || sideB &lt;= 0 || sideC &lt;= 0 ||
            (sideA + sideB &lt;= sideC) || (sideA + sideC &lt;= sideB) || (sideB + sideC &lt;= sideA)) {
            throw new IllegalArgumentException("Invalid triangle sides.");
        }
        this.sideA = sideA;
        this.sideB = sideB;
        this.sideC = sideC;
        // For area, we might need base and height or use Heron's formula if only sides are given.
        // Let's assume for this constructor, area calculation would need additional info or Heron's.
        // For simplicity, we'll make a second constructor for base/height for area,
        // or a method to set base/height if they are not explicitly part of the constructor.
    }

    // Constructor for area (given base and height) and perimeter (given three sides)
    public Triangle(double base, double height, double sideA, double sideB, double sideC) {
        this(sideA, sideB, sideC); // Call the other constructor to validate sides
        if (base &lt;= 0 || height &lt;= 0) {
            throw new IllegalArgumentException("Base and height must be positive.");
        }
        this.base = base;
        this.height = height;
    }

    // Area of a triangle: 0.5 * base * height
    // If only sides are known, Heron's formula would be used.
    @Override
    public double getArea() {
        if (base &gt; 0 && height &gt; 0) {
            return 0.5 * base * height;
        } else {
            // Using Heron's formula if base/height not provided, assuming sides are valid.
            double s = (sideA + sideB + sideC) / 2; // semi-perimeter
            return sqrt(s * (s - sideA) * (s - sideB) * (s - sideC));
        }
    }

    // Perimeter of a triangle: sideA + sideB + sideC
    @Override
    public double getPerimeter() {
        return sideA + sideB + sideC;
    }

    @Override
    public String toString() {
        return super.toString() + ", Sides: " + sideA + ", " + sideB + ", " + sideC +
               (base &gt; 0 && height &gt; 0 ? ", Base: " + base + ", Height: " + height : "");
    }
}

// Ellipse.java
// Ellipse extends Shape and implements area and perimeter calculation for an ellipse.
// Perimeter of an ellipse has no simple exact formula, using Ramanujan's approximation.
class Ellipse extends Shape {
    private double semiMajorAxis; // 'a'
    private double semiMinorAxis; // 'b'

    public Ellipse(double semiMajorAxis, double semiMinorAxis) {
        super("Ellipse");
        if (semiMajorAxis &lt;= 0 || semiMinorAxis &lt;= 0) {
            throw new IllegalArgumentException("Semi-axes must be positive.");
        }
        this.semiMajorAxis = Math.max(semiMajorAxis, semiMinorAxis); // Ensure a &gt;= b
        this.semiMinorAxis = Math.min(semiMajorAxis, semiMinorAxis);
    }

    public double getSemiMajorAxis() {
        return semiMajorAxis;
    }

    public double getSemiMinorAxis() {
        return semiMinorAxis;
    }

    // Area of an ellipse: PI * a * b
    @Override
    public double getArea() {
        return PI * semiMajorAxis * semiMinorAxis;
    }

    // Perimeter of an ellipse (Ramanujan's second approximation):
    // PI * [3*(a+b) - sqrt((3a+b)*(a+3b))]
    @Override
    public double getPerimeter() {
        double a = semiMajorAxis;
        double b = semiMinorAxis;
        return PI * (3 * (a + b) - sqrt((3 * a + b) * (a + 3 * b)));
    }

    @Override
    public String toString() {
        return super.toString() + ", Semi-major Axis: " + semiMajorAxis + ", Semi-minor Axis: " + semiMinorAxis;
    }
}

// ShapeCalculator.java
// Main class to demonstrate the Shape hierarchy and calculations.
public class ShapeCalculator {
    public static void main(String[] args) {
        // Create an array of Shape objects
        Shape[] shapes = new Shape[5];

        shapes[0] = new Circle(5.0);
        shapes[1] = new Rectangle(4.0, 6.0);
        shapes[2] = new Square(5.0); // A square is a type of rectangle
        shapes[3] = new Triangle(3.0, 4.0, 5.0); // Right-angled triangle (sides)
        shapes[4] = new Ellipse(7.0, 4.0);

        System.out.println("--- Shape Calculations ---");
        for (Shape shape : shapes) {
            System.out.println(shape);
            System.out.printf("  Area: %.2f\n", shape.getArea());
            System.out.printf("  Perimeter: %.2f\n", shape.getPerimeter());
            System.out.println();
        }

        // Demonstrating a triangle with base and height
        Triangle triangleWithBaseHeight = new Triangle(6.0, 4.0, 5.0, 6.0, 7.0);
        System.out.println(triangleWithBaseHeight);
        System.out.printf("  Area (using base/height): %.2f\n", triangleWithBaseHeight.getArea());
        System.out.printf("  Perimeter: %.2f\n", triangleWithBaseHeight.getPerimeter());
        System.out.println();

        // Example of invalid input
        try {
            new Circle(-2.0);
        } catch (IllegalArgumentException e) {
            System.out.println("Error creating Circle: " + e.getMessage());
        }
        try {
            new Triangle(1.0, 2.0, 10.0); // Invalid triangle sides
        } catch (IllegalArgumentException e) {
            System.out.println("Error creating Triangle: " + e.getMessage());
        }
    }
}

1. Краткое содержание

1.1 Абстрактные классы и методы
Abstract class — класс с ключевым словом abstract, который нельзя создать напрямую через new. Это общий чертёж: общие свойства и поведение заданы, но «жить» в программе должен уже конкретный тип — как вместо абстрактной «еды» на стол попадают яблоки или шоколад, так вместо абстрактного Vehicle создаются машина, мотоцикл и т.д.

1.1.1 Зачем нужны abstract classes

Logical grouping: родственные классы собираются под общим зонтиком — например, Lion, Cat, Dog под абстрактным Animal.
Enforcing implementation: можно объявить abstract methods — без тела; любой concrete (неабстрактный) subclass обязан их реализовать, сохраняя контракт и разрешая разную реализацию.



1.1.2 Объявление abstract class
Абстрактный класс помечается abstract:
abstract class Vehicle {
    // Regular fields (common to all vehicles)
    Color color;
    int numWheels;

    // Abstract method - no implementation
    abstract void startEngine();

    // Concrete method - has implementation
    void honk() {
        System.out.println("Beep beep!");
    }
}


1.1.3 Abstract methods
Abstract method — объявление метода без тела (без фигурных скобок с кодом); ключевое слово abstract и точка с запятой:
abstract void startEngine();
Так задаётся контракт: у каждого транспорта должен быть способ start engine, но реализация зависит от конкретного типа.


1.1.4 Основные правила

Abstract class нельзя инстанцировать напрямую: недопустимо new Vehicle().
Если в классе есть хотя бы один abstract method, класс должен быть abstract.
В одном abstract class сочетаются abstract и concrete (обычные) методы.
Abstract methods в классе не обязаны быть (редкий случай).
Concrete subclass реализует все унаследованные abstract methods или сам остаётся abstract.
У abstract class могут быть конструкторы, static и final методы.
Поля — с любыми модификаторами (private, protected, public, package-private).



1.1.5 Реализация
Неабстрактный класс, расширяющий abstract class, должен дать тела всем abstract methods:
class Motorcycle extends Vehicle {
    @Override
    void startEngine() {
        System.out.println("Kick start!");
    }
}
Теперь Motorcycle — concrete class, допустимо Motorcycle bike = new Motorcycle();.
Если подкласс не реализовал все abstract methods, он остаётся abstract:
abstract class FlyingVehicle extends Vehicle {
    // startEngine() is still not implemented
    // So FlyingVehicle must be abstract
}



1.2 Final classes и методы
Ключевое слово final ограничивает расширяемость: запрещает наследование или переопределение (в зависимости от контекста).

1.2.1 Final class
Final class нельзя расширять: после final ни один класс не может extends этот класс:
final class Human extends Animal {
    // ... implementation
}

// This would cause a compiler error:
// class SuperHuman extends Human { }  // ERROR!


1.2.2 Final methods
Final method нельзя override в подклассах — поведение зафиксировано для всей иерархии:
class Animal {
    final void breathe() {
        System.out.println("Breathing oxygen");
    }
}

class Dog extends Animal {
    // This would cause a compiler error:
    // void breathe() { }  // ERROR! Cannot override final method
}


1.2.3 Final fields
Final field (constant в смысле однократной инициализации) можно присвоить только один раз после инициализации:
public class Circle {
    private final double radius;  // Must be initialized

    public Circle(double r) {
        radius = r;  // Initialization in constructor
    }

    // radius cannot be changed after this point
}
По конвенции static final поля класса пишут в UPPER_SNAKE_CASE:
public static final double PI = 3.14159265359;



1.3 Interfaces
Interface — ссылочный тип в Java, задающий contract: набор сигнатур методов, которые обязан предоставить implementing class. В отличие от abstract class, интерфейс ближе к pure abstraction: описано что сделать, а не как.

1.3.1 Зачем interfaces

Multiple «inheritance» of type: множественного наследования классов в Java нет, но класс может implement несколько интерфейсов — Duck и Swimmable, и Flyable.
Standardization: контракты вроде Comparable сразу говорят, что объект можно сравнивать.
Decoupling: код может зависеть от интерфейса, а не от concrete class — проще менять реализации и тестировать.



1.3.2 Объявление interface
Ключевое слово interface:
interface Swimmable {
    void swim();           // Abstract method (implicitly public abstract)
    void stopSwimming();   // Abstract method
}

interface Flyable {
    void fly();
    void stopFlying();
}
Начиная с Java 8, в interface допускаются:

Default methods: реализация по умолчанию с ключевым словом default.
Static methods: утилиты на уровне самого интерфейса.

interface Living {
    default void live() {
        System.out.println(this.getClass().getSimpleName() + " lives");
    }
}


1.3.3 implements
Класс подключает интерфейсы через implements (несколько — через запятую):
class Duck implements Swimmable, Flyable, Living {
    @Override
    public void swim() {
        System.out.println("Duck is swimming");
    }

    @Override
    public void stopSwimming() {
        System.out.println("Duck stopped swimming");
    }

    @Override
    public void fly() {
        System.out.println("Duck is flying");
    }

    @Override
    public void stopFlying() {
        System.out.println("Duck stopped flying");
    }

    // live() method is inherited from Living interface (default method)
}


1.3.4 Свойства interface

Методы по умолчанию implicitly public abstract (кроме default и static).
Поля в interface — implicitly public static final (константы).
Класс может implement несколько интерфейсов, но extends только один класс.
Интерфейс может extends другой интерфейс (или несколько).
Интерфейс не может extends класс.
Интерфейс нельзя инстанцировать через new.




1.4 Abstract class vs. interface
Важно понимать, когда выбирать abstract class, а когда interface.

1.4.1 Ключевые отличия








Аспект
