// Person.java
class Person {
    private String name;
    private int age;

    public Person(String initialName) {
        this.name = initialName;
        this.age = 0;
    }

    public Person(String initialName, int initialAge) {
        this.name = initialName;
        this.age = initialAge;
    }

    public void printPerson() {
        System.out.println(name + ", age: " + age + " years");
    }

