        System.out.println("Car: " + model);
        System.out.println("Wheels:");
        for (int i = 0; i &lt; 4; i++) {
            System.out.print("  Position " + i + ": ");
            if (wheels[i] != null) {
                wheels[i].displayWheel();
            } else {
                System.out.println("No wheel");
